const data = msg.payload;

if (!data || typeof data !== "object") {
    node.warn("Invalid MQTT payload");
    return null;
}

if (
    data.facility_id !== "warehouse" ||
    data.device_id !== "esp32-wokwi-01" ||
    typeof data.temperature !== "number" ||
    typeof data.humidity !== "number"
) {
    node.warn("Unexpected ESP32 sensor data");
    return null;
}

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    facility_id: data.facility_id,
    device_id: data.device_id,
    temperature: data.temperature,
    humidity: data.humidity,
    rule_status: data.rule_status
};

return msg;

const data = msg.payload;

if (!data || typeof data.temperature !== "number") {
    node.warn("Invalid temperature reading");
    return null;
}

const temperature = data.temperature;

let status = "NORMAL";

if (temperature < 15 || temperature > 30) {
    status = "ANOMALY";
}

msg.payload = {
    facility_id: data.facility_id,
    device_id: data.device_id,
    temperature: temperature,
    unit: "°C",
    status: status
};

node.status({
    fill: status === "NORMAL" ? "green" : "red",
    shape: "dot",
    text: `${temperature.toFixed(1)} °C | ${status}`
});

return msg;

const data = msg.payload;

if (
    !data ||
    typeof data.humidity !== "number" ||
    !Number.isFinite(data.humidity)
) {
    node.warn("Invalid humidity reading");
    return null;
}

const humidity = data.humidity;

let status = "NORMAL";

if (humidity < 30 || humidity > 70) {
    status = "ANOMALY";
}

msg.payload = {
    facility_id: data.facility_id,
    device_id: data.device_id,
    humidity: humidity,
    unit: "%",
    status: status
};

node.status({
    fill: status === "NORMAL" ? "green" : "red",
    shape: "dot",
    text: `${humidity.toFixed(1)}% | ${status}`
});

return msg;

const response = msg.payload;

if (!response || !response.analysis) {
    node.warn("Missing FastAPI AI analysis");
    return null;
}

const analysis = response.analysis;

const status = analysis.status;
const aiStatus = analysis.ai_status;
const ruleStatus = analysis.rule_status;

if (!["NORMAL", "ANOMALY"].includes(status)) {
    node.warn("Invalid hybrid anomaly status");
    return null;
}

const isAnomaly = status === "ANOMALY";

msg.payload = {
    facility_id: response.facility_id,
    device_id: response.device_id,
    temperature: analysis.temperature,
    humidity: analysis.humidity,
    ai_status: aiStatus,
    rule_status: ruleStatus,
    hybrid_status: status,
    anomaly_score: analysis.anomaly_score,
    rule_alerts: analysis.rule_alerts,
    alert: isAnomaly
        ? "WARNING: Anomaly detected!"
        : "Environment operating normally"
};

node.status({
    fill: isAnomaly ? "red" : "green",
    shape: "dot",
    text: isAnomaly
        ? "AI ALERT: ANOMALY"
        : "AI STATUS: NORMAL"
});

return msg;
